def __getitem__(self, address):
    return unpack_float32(self.read_bytes(address))

def __setitem__(self, address, value):
    validate_address(address)
    self.data[address:address + 4] = pack_float32(value)
    self.view_starts.add(address)

def read_bytes(self, address):
    validate_address(address)
    return bytes(self.data[address:address + 4])

def pack_float32(value):
    """Round a value to four little-endian IEEE 754 binary32 bytes.

    Python struct applies round-to-nearest, ties-to-even. Values too large for
    finite binary32 become signed infinity, rather than aborting a store.
    """
    try:
        return struct.pack('<f', value)
    except OverflowError:
        return struct.pack('<f', math.copysign(math.inf, value))


def unpack_float32(data):
    return struct.unpack('<f', data)[0]
